import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r"\(.+?\)|\w") -> dict:
    directory = Path(directory_path)

    if not directory.is_dir():
        return {}

    try:
        pattern = re.compile(regex_pattern)
    except re.error:
        return {}

    results = {}

    for file_name in glob.glob(str(directory / "*.txt")):
        file_path = Path(file_name)

        if not file_path.is_file():
            continue

        try:
            content = file_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            continue

        results[file_path.name] = pattern.findall(content)

    return results

import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt


def task_func(s1, s2):
    if not isinstance(s1, pd.Series) or not isinstance(s2, pd.Series):
        raise TypeError("s1 and s2 must be pandas Series")

    values1 = s1.dropna().unique()
    values2 = s2.dropna().unique()
    intersection = set(values1).intersection(values2)

    data = pd.DataFrame({
        "value": pd.concat([s1, s2], ignore_index=True),
        "series": ["s1"] * len(s1) + ["s2"] * len(s2),
    }).dropna(subset=["value"])

    _, ax = plt.subplots()

    if not data.empty:
        sns.swarmplot(
            data=data,
            x="series",
            y="value",
            ax=ax,
        )

    for value in intersection:
        ax.axhline(value, color="red", linestyle="--")

    return ax, len(intersection)
